\section*{矩阵运算基础}

\subsection*{矩阵乘法}
设 $A$ 是 $m \times n$ 矩阵，$B$ 是 $n \times p$ 矩阵，则 $C = AB$ 是 $m \times p$ 矩阵，其中：
$$c_{ij} = \sum_{k=1}^{n} a_{ik} b_{kj}$$

\subsection*{矩阵乘法示例}
$$
\begin{pmatrix}
1 & 2 & 3 \\
4 & 5 & 6
\end{pmatrix}
\begin{pmatrix}
7 & 8 \\
9 & 10 \\
11 & 12
\end{pmatrix}
=
\begin{pmatrix}
1 \cdot 7 + 2 \cdot 9 + 3 \cdot 11 & 1 \cdot 8 + 2 \cdot 10 + 3 \cdot 12 \\
4 \cdot 7 + 5 \cdot 9 + 6 \cdot 11 & 4 \cdot 8 + 5 \cdot 10 + 6 \cdot 12
\end{pmatrix}
=
\begin{pmatrix}
58 & 64 \\
139 & 154
\end{pmatrix}
$$

\subsection*{行列式}
$2 \times 2$ 行列式：
$$\det \begin{pmatrix}
a & b \\
c & d
\end{pmatrix} = ad - bc$$

$3 \times 3$ 行列式：
$$
\det \begin{pmatrix}
a & b & c \\
d & e & f \\
g & h & i
\end{pmatrix}
= a(ei - fh) - b(di - fg) + c(dh - eg)
$$

\end{document}
```

