```latex
\documentclass{article}
\usepackage{amsmath}
\usepackage{amssymb}
\usepackage{tikz}
\pgfplotsset{compat=1.18}

\begin{document}

\section*{梯度下降算法}

\subsection*{目标函数}
假设我们要最小化目标函数 $J(\theta)$，其中 $\theta$ 是参数向量。

\subsection*{梯度下降更新规则}
参数更新公式：
$$\theta := \theta - \alpha \nabla_\theta J(\theta)$$

其中：
\begin{itemize}
\item $\alpha$ 是学习率（learning rate）
\item $\nabla_\theta J(\theta)$ 是目标函数关于参数 $\theta$ 的梯度
\end{itemize}

\subsection*{线性回归的梯度下降}
对于线性回归 $h_\theta(x) = \theta_0 + \theta_1 x$，代价函数为：
$$J(\theta) = \frac{1}{2m} \sum_{i=1}^{m} (h_\theta(x^{(i)}) - y^{(i)})^2$$

参数更新：
\begin{align}
\theta_0 &:= \theta_0 - \alpha \frac{1}{m} \sum_{i=1}^{m} (h_\theta(x^{(i)}) - y^{(i)}) \\
\theta_1 &:= \theta_1 - \alpha \frac{1}{m} \sum_{i=1}^{m} (h_\theta(x^{(i)}) - y^{(i)}) x^{(i)}
\end{align}

\subsection*{批量梯度下降 vs 随机梯度下降}
\begin{itemize}
\item \textbf{批量梯度下降}：每次更新使用所有训练样本
\item \textbf{随机梯度下降}：每次更新只使用一个随机训练样本
\item \textbf{小批量梯度下降}：每次更新使用一小批训练样本
\end{itemize}

\subsection*{梯度下降示意图}
\begin{center}
\begin{tikzpicture}[scale=0.9]
\begin{axis}[
    domain=-2:2,
    samples=100,
    axis lines=left,
    xlabel={$\theta$},
    ylabel={$J(\theta)$},
    ymin=0,
    ymax=5,
    legend pos=north west,
    grid=major
]
\addplot[blue,thick] {x^2 - 0.5*x + 1};
\addplot[red,mark=*,only marks] coordinates {(-0.25,0.9375)};
\addplot[orange,mark=*,only marks] coordinates {(-0.25,0.9375)};
\addplot[orange,mark=*,only marks] coordinates {(0.25,0.8125)};
\addplot[green!70!black,mark=*,only marks] coordinates {(0.125,0.859375)};
\addplot[purple,mark=*,only marks] coordinates {(0.0625,0.8828125)};
\addplot[purple,mark=*,only marks] coordinates {(0.03125,0.896484375)};
\legend{$J(\theta)$, 初始点, 梯度下降路径}
\end{axis}
\end{tikzpicture}
\end{center}

\subsection*{学习率的选择}
\begin{itemize}
\item 学习率太大：可能震荡或发散
\item 学习率太小：收敛速度慢
\item 可以使用学习率衰减策略
\end{itemize}

\end{document}
```

